-- ISO/IEC 27001:2022 Annex A (framework iso-27001-2022): all 93 controls.
-- Technological controls (A.8) a scan can evidence are measured — technical
-- vulnerabilities (KEV, SLA), secure coding and configuration (CWE classes,
-- Checkov/Trivy checks), cryptography, logging, access and network security,
-- plus the A.8 Prowler checks from Prowler's ISO 27001:2022 packs. Organisational
-- (A.5), people (A.6) and physical (A.7) controls, and the other A.8 controls,
-- are manual. Titles are paraphrased, never the standard's text.

INSERT INTO frameworks (key, name, version, description)
VALUES ('iso-27001-2022', 'ISO/IEC 27001:2022 Annex A', '2022',
        'The 93 Annex A controls of ISO/IEC 27001:2022. Technological controls (A.8) a scan can evidence — vulnerabilities, secure coding, configuration, cryptography, logging, access and network security — are measured; organisational, people and physical controls are attested. Titles are paraphrased; consult the standard for the control text.');

